const TEST_BANKS = {
  1: TEST_ONE_QUESTIONS,
  2: TEST_TWO_QUESTIONS.map((q, i) => ({...q, o:[...q.o], a:TEST_TWO_ANSWER_KEY[i]})),
  3: [...TEST_ONE_QUESTIONS.slice(0,15), ...TEST_TWO_QUESTIONS.slice(15,30).map((q,i)=>({...q,o:[...q.o],a:TEST_TWO_ANSWER_KEY[i+15]}))],
  4: TEST_FOUR_QUESTIONS.map(q => ({...q, o:[...q.o]}))
};
let activeTestNumber = 1;
