const $ = id => document.getElementById(id);
let studentName="", current=0, answers=Array(30).fill(null), secondsLeft=1800, timerInterval=null, finished=false;
function startTest(name){studentName=name.trim();if(!studentName)return;QUESTIONS=TEST_BANKS[activeTestNumber];activeTestTitle=({1:"1-test — Huquq",2:"2-test — Yangi variant",3:"3-test — Aralash sinov",4:"4-test — Tarix va huquq amaliyoti"})[activeTestNumber]||"Huquq testi";$("welcomeScreen").classList.add("hidden");$("resultScreen").classList.add("hidden");$("quizScreen").classList.remove("hidden");$("welcomeStudent").textContent=activeTestTitle+" · Ishtirokchi: "+studentName;current=0;answers=Array(QUESTIONS.length).fill(null);secondsLeft=QUESTIONS.length*60;finished=false;renderQuestion();renderGrid();updateProgress();updateTimer();clearInterval(timerInterval);timerInterval=setInterval(()=>{secondsLeft--;updateTimer();if(secondsLeft<=0)finishTest(true)},1000);window.scrollTo({top:0,behavior:"smooth"})}
function updateTimer(){let m=Math.floor(secondsLeft/60),s=secondsLeft%60;$("timer").textContent=String(m).padStart(2,"0")+":"+String(s).padStart(2,"0");$("timer").parentElement.classList.toggle("warning",secondsLeft<=300)}
function renderQuestion(){const item=QUESTIONS[current];$("questionNumber").textContent="SAVOL "+String(current+1).padStart(2,"0");$("questionText").textContent=item.q;$("navCounter").textContent=(current+1)+" / "+QUESTIONS.length;$("prevBtn").disabled=current===0;$("prevBtn").style.opacity=current===0?".45":"1";$("nextBtn").textContent=current===QUESTIONS.length-1?"Oxirgi savol ✓":"Keyingi →";const list=$("optionsList");list.innerHTML="";item.o.forEach((option,i)=>{const b=document.createElement("button");b.type="button";b.className="option"+(answers[current]===i?" selected":"");const letter=document.createElement("span");letter.className="option-letter";letter.textContent="ABCD"[i];const text=document.createElement("span");text.textContent=option;b.append(letter,text);b.addEventListener("click",()=>{answers[current]=i;renderQuestion();renderGrid();updateProgress()});list.appendChild(b)});renderGrid()}
function renderGrid(){const grid=$("questionGrid");grid.innerHTML="";QUESTIONS.forEach((_,i)=>{const b=document.createElement("button");b.type="button";b.className="q-jump"+(i===current?" current":"")+(answers[i]!==null?" answered":"");b.textContent=i+1;b.addEventListener("click",()=>{current=i;renderQuestion()});grid.appendChild(b)})}
function updateProgress(){const n=answers.filter(a=>a!==null).length;$("progressText").textContent=n+" / "+QUESTIONS.length+" javob";$("progressBar").style.width=(n/QUESTIONS.length*100)+"%"}
function finishTest(auto=false){if(finished)return;if(!auto){const n=answers.filter(a=>a===null).length;if(n&&!confirm(n+" ta savol javobsiz. Testni yakunlaysizmi?"))return;if(!confirm("Testni yakunlashni tasdiqlaysizmi?"))return}finished=true;clearInterval(timerInterval);const correct=answers.filter((a,i)=>a===QUESTIONS[i].a).length,wrong=answers.filter((a,i)=>a!==null&&a!==QUESTIONS[i].a).length,empty=answers.filter(a=>a===null).length,pct=Math.round(correct/QUESTIONS.length*100);$("quizScreen").classList.add("hidden");$("resultScreen").classList.remove("hidden");$("resultName").textContent=studentName;$("scorePercent").textContent=pct+"%";$("scoreFraction").textContent=correct+" / "+QUESTIONS.length;$("correctCount").textContent=correct;$("wrongCount").textContent=wrong;$("emptyCount").textContent=empty;$("scoreCircle").style.setProperty("--score-angle",pct*3.6+"deg");$("scoreMessage").textContent=pct>=85?"Ajoyib natija! Bilimingiz juda yaxshi.":pct>=60?"Yaxshi natija! Yana biroz mashq qiling.":"Natijangizni tahlil qiling va qayta urinib ko‘ring.";
const certificateReady = wrong <= 2 && empty === 0;
$("certificatePanel").classList.toggle("hidden", !certificateReady);
$("certificateName").textContent = "MURODOV NURBEK";
const review=$("reviewList");review.innerHTML="";QUESTIONS.forEach((item,i)=>{const user=answers[i],ok=user===item.a,card=document.createElement("article");card.className="review-item "+(user===null?"review-empty":ok?"review-correct":"review-wrong");const top=document.createElement("div");top.className="review-top";const label=document.createElement("span");label.className="review-label";label.textContent="SAVOL "+String(i+1).padStart(2,"0");const status=document.createElement("span");status.className="review-status";status.textContent=user===null?"JAVOBSIZ":ok?"TO‘G‘RI":"NOTO‘G‘RI";top.append(label,status);const q=document.createElement("h3");q.textContent=item.q;const opts=document.createElement("div");opts.className="review-options";item.o.forEach((opt,j)=>{const row=document.createElement("div");row.className="review-option"+(j===item.a?" is-correct":"")+(user===j&&user!==item.a?" is-wrong":"");row.textContent="ABCD"[j]+") "+opt+(j===item.a?" — To‘g‘ri javob":user===j?" — Sizning javobingiz":"");opts.appendChild(row)});const ex=document.createElement("div");ex.className="explanation";const bold=document.createElement("b");bold.textContent="Izoh: ";ex.append(bold,document.createTextNode(item.e));card.append(top,q,opts,ex);review.appendChild(card)});window.scrollTo({top:0,behavior:"smooth"})}
$("startForm").addEventListener("submit",e=>{e.preventDefault();if(localStorage.getItem("tarixNurbekChannelConfirmed")!=="yes"){ $("channelAd").classList.remove("hidden"); alert("Avval Tarix Nurbek kanaliga obuna bo‘ling, so‘ng tasdiqlash tugmasini bosing."); return; } startTest($("studentName").value)});$("prevBtn").addEventListener("click",()=>{if(current>0){current--;renderQuestion()}});$("nextBtn").addEventListener("click",()=>{if(current<QUESTIONS.length-1){current++;renderQuestion()}else document.querySelector(".question-card").scrollIntoView({behavior:"smooth"})});$("finishBtn").addEventListener("click",()=>finishTest(false));
$("retryWrongBtn").addEventListener("click",()=>{const wrongItems=QUESTIONS.filter((q,i)=>answers[i]!==q.a);if(!wrongItems.length){alert("Xato javoblar yo‘q — ajoyib!");return;}QUESTIONS=wrongItems.map(q=>({...q,o:[...q.o]}));activeTestTitle += " — xatolarni qayta ishlash";$("resultScreen").classList.add("hidden");$("quizScreen").classList.remove("hidden");current=0;answers=Array(QUESTIONS.length).fill(null);secondsLeft=QUESTIONS.length*60;finished=false;$("welcomeStudent").textContent=activeTestTitle+" · Ishtirokchi: "+studentName;renderQuestion();renderGrid();updateProgress();updateTimer();clearInterval(timerInterval);timerInterval=setInterval(()=>{secondsLeft--;updateTimer();if(secondsLeft<=0)finishTest(true)},1000);window.scrollTo({top:0,behavior:"smooth"});});
$("restartBtn").addEventListener("click",()=>{$("resultScreen").classList.add("hidden");$("welcomeScreen").classList.remove("hidden");$("studentName").value=studentName;window.scrollTo({top:0,behavior:"smooth"})});

