$("printCertificateBtn").addEventListener("click", () => {
  if (answers.filter((a,i)=>a!==null && a!==QUESTIONS[i].a).length > 2 || answers.some(a=>a===null)) return;
  const win = window.open("", "_blank");
  if (!win) { alert("Brauzer yangi oynani blokladi. Qayta urinib ko‘ring."); return; }
  win.document.write(`<!doctype html><html lang="uz"><head><meta charset="utf-8"><title>Sertifikat</title><style>
  body{margin:0;font-family:Georgia,serif;background:#f3f0e7;color:#17223b}.certificate{margin:5vh auto;padding:48px 35px;max-width:850px;min-height:480px;border:12px double #b58b38;text-align:center;background:#fffdf6;box-sizing:border-box}.eyebrow{letter-spacing:4px;color:#9b7429;font: bold 13px Arial}.seal{font-size:46px;color:#b58b38;margin:14px}.title{font-size:42px;margin:20px 0;color:#17223b}.name{font-size:32px;color:#9b7429;border-bottom:1px solid #c5aa6b;display:inline-block;padding:8px 25px}.desc{font:16px/1.8 Arial;margin:24px auto;max-width:620px}.foot{margin-top:45px;font:14px Arial}button{padding:12px 20px;background:#17223b;color:white;border:0;border-radius:8px}@media print{button{display:none}.certificate{margin:0;min-height:95vh}}</style></head><body><main class="certificate"><div class="eyebrow">HUQUQ ONLINE TEST PLATFORMASI</div><div class="seal">✦ § ✦</div><h1 class="title">SERTIFIKAT</h1><p>Ushbu sertifikat</p><div class="name">MURODOV NURBEK</div><p class="desc">${activeTestTitle} sinovida 2 ta yoki undan kam xato bilan muvaffaqiyatli natijaga erishganini tasdiqlaydi.</p><div class="foot">Muallif: <b>Murodov Nurbek</b><br><br>Natija: ${$("scorePercent").textContent} · ${new Date().toLocaleDateString("uz-UZ")}</div><p><button onclick="window.print()">Chop etish / PDF saqlash</button></p></main></body></html>`);
  win.document.close();
});
function selectTest(testNumber) {
  activeTestNumber = testNumber;
  document.querySelectorAll(".library-card[data-test]").forEach(card => {
    const selected = Number(card.dataset.test) === testNumber;
    card.classList.toggle("active", selected);
    card.setAttribute("aria-pressed", String(selected));
  });
  const titles = {1:"1-test tanlandi. Asosiy huquq savollari.",2:"2-test tanlandi. Yangi savollar to‘plami.",3:"3-test tanlandi. Aralash sinov.",4:"4-test tanlandi. Huquqshunoslik bo‘yicha yangi, original amaliy savollar."};
  $("newTestNotice").classList.remove("hidden");
  $("newTestNotice").textContent = titles[testNumber] || titles[1];
  $("studentName").focus({preventScroll:true});
  $("startForm").scrollIntoView({behavior:"smooth", block:"center"});
}
