$("exportResultBtn").addEventListener("click", () => {
  const lines = [
    "TARIX HUQUQ NURBEK — TEST NATIJASI",
    "Test: " + activeTestTitle,
    "Ishtirokchi: " + studentName,
    "Natija: " + $("scoreFraction").textContent + " (" + $("scorePercent").textContent + ")",
    "To‘g‘ri: " + $("correctCount").textContent,
    "Noto‘g‘ri: " + $("wrongCount").textContent,
    "Javobsiz: " + $("emptyCount").textContent,
    "",
    ...QUESTIONS.map((item, i) => {
      const chosen = answers[i] === null ? "Javobsiz" : "ABCD"[answers[i]] + ") " + item.o[answers[i]];
      return (i+1)+". "+item.q.replace(/\n/g," ")+"\nSizning javobingiz: "+chosen+"\nTo‘g‘ri javob: "+"ABCD"[item.a]+") "+item.o[item.a];
    })
  ];
  const blob = new Blob([lines.join("\n\n")], {type:"text/plain;charset=utf-8"});
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = "huquq-test-natijasi.txt"; a.click();
  URL.revokeObjectURL(url);
});
